'use strict';
const $=s=>document.querySelector(s);
const stories={health:{label:'01 / HEALTH.AI',title:'Making symptoms<br>easier to navigate.',intro:'A full-stack health information project that combines natural-language processing, semantic retrieval, and a usable interface.',sections:[['The build','I paired a fine-tuned MiniLM encoder with an ensemble classifier, achieving 88.7% top-1 accuracy in project evaluation. That result describes the evaluated classification task, not clinical accuracy.'],['Beyond classification','Semantic retrieval and triage flag emergencies outside the trained label set. The Flask + React application also includes diet plans, calendar reminders, and a pharmacy locator.'],['The engineering question','How do you turn an uncertain language input into a useful experience? This project brings model behavior, retrieval, and interface design into the same workflow.']],links:[['View project','https://health-ai-xck8.onrender.com/'],['Explore the code','https://github.com/adipatel399/Health.AI']],note:'Personal project for health information. It is not a medical diagnosis service or a substitute for professional care.'},bnp:{label:'02 / BNP PARIBAS · JAN–JUL 2026',title:'Working through<br>enterprise complexity.',intro:'As an AI Engineer Intern in Mumbai, I worked on automation, retrieval, and workflow reliability.',sections:[['The work','I developed Playwright MCP automation to validate complex user workflows, and implemented RAG workflows using LangChain and vector databases for semantic search across 10,000+ documents.'],['The result','My résumé reports a 30% reduction in manual effort for the AI-driven workflows I worked on. I also used AI agents and LoadRunner for testing and performance analysis.'],['What this shows','The work connects AI development to operational usefulness: finding information, validating workflows, and reducing repetitive tasks.']],links:[['Connect on LinkedIn','https://www.linkedin.com/in/aditya399/']],note:'Internship summary based on my résumé. Internal code, documents, and confidential implementation details are not published.'},rocky:{label:'03 / ROCKY',title:'A companion.<br>A voice.<br>A working system.',intro:'A voice-controlled macOS companion inspired by Rocky from Project Hail Mary.',sections:[['Local by design','Wake-word detection and speech-to-text run on the machine using openWakeWord and Whisper. Listening and transcription stay local; other application capabilities may use external services.'],['A faster route','For supported live-data queries, a direct intent-to-provider router bypasses the LLM. My project reports replies in about one second for those queries.'],['A spatial interface','A three-dimensional globe flies to locations and surfaces weather, news, and Wikipedia information. The stack includes Python, FastAPI, JavaScript, three.js, and globe.gl.']],links:[['Explore the code','https://github.com/adipatel399/Rocky']],note:'Existing project showcased in this newly built portfolio.'}};
function openStory(id){const s=stories[id];if(!s)return;$('#story-content').innerHTML=`<div class="section-label">${s.label}</div><h2>${s.title}</h2><p>${s.intro}</p>${s.sections.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}<div class="links">${s.links.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener">${t} ↗</a>`).join('')}</div><p class="note">${s.note}</p>`;if(running&&!paused)pauseGame();$('#story-dialog').showModal()}
document.querySelectorAll('[data-story]').forEach(b=>b.addEventListener('click',()=>openStory(b.dataset.story)));$('.close').onclick=()=>$('#story-dialog').close();$('#story-dialog').addEventListener('click',e=>{if(e.target===$('#story-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const orb=$('#orb'),oc=orb.getContext('2d');let ow=0,oh=0,rotation=0,tilt=.4,drag=false,px=0;
function fit(c){const r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);c.width=Math.round(r.width*d);c.height=Math.round(r.height*d);c.getContext('2d').setTransform(d,0,0,d,0,0);return [r.width,r.height]}
function drawOrb(t){oc.clearRect(0,0,ow,oh);let angle=rotation+(reduced?0:t*.00016),scale=Math.min(ow,oh)*.31;const project=(u,v)=>{let a=1+.36*Math.cos(v),x=a*Math.cos(u),z=a*Math.sin(u),y=.36*Math.sin(v);let xx=x*Math.cos(angle)-z*Math.sin(angle),zz=x*Math.sin(angle)+z*Math.cos(angle);let yy=y*Math.cos(tilt)-zz*Math.sin(tilt),depth=y*Math.sin(tilt)+zz*Math.cos(tilt);let p=3.7/(3.7+depth);return [ow*.52+xx*scale*p,oh*.48+yy*scale*p,depth]};for(let v=0;v<24;v++){oc.beginPath();let dep=0;for(let u=0;u<=100;u++){const [x,y,z]=project(u/100*Math.PI*2,v/24*Math.PI*2);dep+=z;u?oc.lineTo(x,y):oc.moveTo(x,y)}oc.strokeStyle=`rgba(198,255,99,${.23+(1-dep/101)*.18})`;oc.lineWidth=.65;oc.stroke()}for(let u=0;u<64;u++){oc.beginPath();for(let v=0;v<=40;v++){const[x,y]=project(u/64*Math.PI*2,v/40*Math.PI*2);v?oc.lineTo(x,y):oc.moveTo(x,y)}oc.strokeStyle='#c6ff6355';oc.lineWidth=.65;oc.stroke()}oc.fillStyle='#c6ff63';oc.fillRect(ow*.52-2,oh*.48-2,4,4);requestAnimationFrame(drawOrb)}
orb.addEventListener('pointerdown',e=>{drag=true;px=e.clientX;orb.setPointerCapture(e.pointerId)});orb.addEventListener('pointermove',e=>{if(drag){rotation+=(e.clientX-px)*.012;px=e.clientX}});orb.addEventListener('pointerup',()=>drag=false);orb.addEventListener('pointercancel',()=>drag=false);
const game=$('#game'),ctx=game.getContext('2d');let gw=0,gh=0,running=false,paused=false,lane=1,drawLane=1,score=0,lives=3,time=45,objects=[],elapsed=0,spawn=0,last=0,best=0,finishText='',unlockTimer;try{best=Number(localStorage.getItem('aditya-signal-best'))||0}catch{}$('#best').textContent='BEST: '+String(best).padStart(2,'0');
function resize(){[ow,oh]=fit(orb);[gw,gh]=fit(game)}window.addEventListener('resize',resize);resize();requestAnimationFrame(drawOrb);
const ids=['health','bnp','rocky'];
function hud(){$('#score').textContent=String(score).padStart(2,'0');$('#lives').textContent=lives;$('#time').textContent=Math.ceil(time);$('#game-status').textContent=paused?'PAUSED':running?'LIVE / FIND THE SIGNAL':'READY WHEN YOU ARE'}
function startGame(){running=true;paused=false;lane=1;drawLane=1;score=0;lives=3;time=45;objects=[];elapsed=0;spawn=.3;$('#game-overlay').style.display='none';$('.game-hud').hidden=false;$('#pause').disabled=false;$('#pause').textContent='Ⅱ';$('#pause').setAttribute('aria-label','Pause game');$('#unlock').style.opacity=0;clearTimeout(unlockTimer);document.querySelectorAll('#unlocks button').forEach(b=>b.disabled=true);hud()}
function endGame(){running=false;paused=false;best=Math.max(best,score);try{localStorage.setItem('aditya-signal-best',best)}catch{}$('#best').textContent='BEST: '+String(best).padStart(2,'0');finishText=lives<=0?'THE NOISE WON.':'SIGNAL FOUND.';$('#game-overlay').innerHTML=`<span class="eyebrow">RUN COMPLETE / ${score} SIGNALS</span><h3>${finishText.split(' ').slice(0,2).join(' ')}<br><em>${finishText.split(' ').slice(2).join(' ')||'NICE RUN.'}</em></h3><p>${score>=15?'All three project stories unlocked.':score>=5?'You unlocked '+Math.min(3,Math.floor(score/5))+' project '+(score>=10?'stories':'story')+'. Explore below.':'Try again for 5 signals to unlock Health.AI.'}</p><button class="pill light" id="play-again">Play again ↗</button><small>Or explore all projects in Selected Work above.</small>`;$('#game-overlay').style.display='flex';$('#play-again').onclick=startGame;$('#pause').disabled=true;$('#game-status').textContent='RUN COMPLETE'}
function pauseGame(){if(!running)return;paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Resume game':'Pause game');$('#game-status').textContent=paused?'PAUSED / PRESS ▶ TO RESUME':'LIVE / FIND THE SIGNAL'}
function move(d){if(running&&!paused)lane=Math.max(0,Math.min(2,lane+d))}
$('#start-game').onclick=startGame;$('#restart').onclick=startGame;$('#pause').onclick=pauseGame;$('#left').onclick=()=>move(-1);$('#right').onclick=()=>move(1);
document.addEventListener('keydown',e=>{if($('#story-dialog').open||!running)return;if(['ArrowLeft','ArrowRight','a','A','d','D',' '].includes(e.key)){e.preventDefault();if(e.key===' ')pauseGame();else move(['ArrowLeft','a','A'].includes(e.key)?-1:1)}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!paused)pauseGame()});
function plane(l,z){const depth=1-z,scale=.06+depth*depth*.94;return [gw/2+(l-1)*gw*.27*scale,gh*.20+gh*.70*scale,scale]}
function drawGame(now){const dt=Math.min((now-last)/1000,.05)||0;last=now;ctx.clearRect(0,0,gw,gh);ctx.fillStyle='#0b100a';ctx.fillRect(0,0,gw,gh);const horizon=gh*.20;const glow=ctx.createRadialGradient(gw/2,horizon,0,gw/2,horizon,gw*.55);glow.addColorStop(0,'#b6ff6415');glow.addColorStop(1,'#0b100a00');ctx.fillStyle=glow;ctx.fillRect(0,0,gw,gh);ctx.lineWidth=1;for(let i=-3;i<=3;i++){ctx.strokeStyle=i===-2||i===2?'#c6ff6350':'#c6ff631c';ctx.beginPath();ctx.moveTo(gw/2+i*gw*.015,horizon);ctx.lineTo(gw/2+i*gw*.23,gh);ctx.stroke()}const scroll=running?elapsed:reduced?0:now*.0002;for(let i=0;i<18;i++){const z=((i/18+scroll*.15)%1),p=z*z;const y=horizon+p*gh*.8;ctx.strokeStyle=`rgba(198,255,99,${p*.18})`;ctx.beginPath();ctx.moveTo(gw/2-gw*p,y);ctx.lineTo(gw/2+gw*p,y);ctx.stroke()}ctx.strokeStyle='#c6ff6317';ctx.beginPath();ctx.moveTo(0,gh*.04);ctx.lineTo(gw/2,horizon);ctx.lineTo(gw,gh*.04);ctx.stroke();
if(running&&!paused){elapsed+=dt;time=Math.max(0,45-elapsed);spawn-=dt;if(spawn<=0){spawn=.56;const signalLane=Math.floor(Math.random()*3);objects.push({lane:signalLane,z:1,type:'signal',hit:false});if(Math.random()<.7)objects.push({lane:(signalLane+1+Math.floor(Math.random()*2))%3,z:1,type:'noise',hit:false})}drawLane+=(lane-drawLane)*Math.min(1,dt*16);for(const o of objects){o.z-=dt*(.29+elapsed*.0012);if(o.z<=.04&&!o.hit){o.hit=true;if(o.lane===lane){if(o.type==='signal'){score++;if(score%5===0&&score<=15){const index=score/5-1;document.querySelectorAll('#unlocks button')[index].disabled=false;$('#unlock').textContent=stories[ids[index]].label+' UNLOCKED';$('#unlock').style.opacity=1;clearTimeout(unlockTimer);unlockTimer=setTimeout(()=>$('#unlock').style.opacity=0,2300)}}else{lives--;game.style.filter='brightness(1.6)';setTimeout(()=>game.style.filter='',120)}}}}objects=objects.filter(o=>o.z>-.1);hud();if(time<=0||lives<=0)endGame()}
objects.filter(o=>!o.hit).sort((a,b)=>b.z-a.z).forEach(o=>{const[x,y,s]=plane(o.lane,o.z),size=27*s;ctx.save();ctx.translate(x,y);if(o.type==='signal'){ctx.rotate(Math.PI/4);ctx.shadowColor='#c6ff63';ctx.shadowBlur=15*s;ctx.fillStyle='#c6ff63';ctx.fillRect(-size/2,-size/2,size,size);ctx.fillStyle='#f1ffdb';ctx.fillRect(-size/5,-size/5,size*.4,size*.4)}else{ctx.strokeStyle='#ff7867';ctx.fillStyle='#ff786733';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-size,-size);ctx.lineTo(size,-size);ctx.lineTo(size,size);ctx.lineTo(-size,size);ctx.closePath();ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(-size*.5,-size*.5);ctx.lineTo(size*.5,size*.5);ctx.moveTo(size*.5,-size*.5);ctx.lineTo(-size*.5,size*.5);ctx.stroke()}ctx.restore()});
if(running){const[x,y]=plane(drawLane,0);ctx.shadowColor='#c6ff63';ctx.shadowBlur=15;ctx.fillStyle='#e7f7d6';ctx.beginPath();ctx.moveTo(x,y-23);ctx.lineTo(x-20,y+15);ctx.lineTo(x,y+6);ctx.lineTo(x+20,y+15);ctx.closePath();ctx.fill();ctx.shadowBlur=0;if(paused){ctx.fillStyle='#0b100a99';ctx.fillRect(0,0,gw,gh);ctx.fillStyle='#c6ff63';ctx.font='500 28px sans-serif';ctx.textAlign='center';ctx.fillText('PAUSED',gw/2,gh/2);ctx.font='12px sans-serif';ctx.fillText('Press Space or the play button to resume',gw/2,gh/2+30)}}requestAnimationFrame(drawGame)}requestAnimationFrame(drawGame);
